 */
public void removeInstanceData(ViewInstanceEntity instanceEntity, String key) {
  ViewInstanceDataEntity dataEntity = instanceEntity.getInstanceData(key);
  if (dataEntity != null) {
    instanceDAO.removeData(dataEntity);
